<?php
// Funções Comuns do Sistema

// Sanitizar dados de entrada
function sanitize($data) {
    $data = trim($data);
    $data = stripslashes($data);
    $data = htmlspecialchars($data);
    return $data;
}

// Validar datas de reserva
function validateDates($checkIn, $checkOut) {
    $today = date('Y-m-d');

    if($checkIn < $today) {
        return "Data de check-in inválida";
    }

    if($checkOut <= $checkIn) {
        return "Data de check-out deve ser maior que check-in";
    }

    return true;
}

// Calcular total da reserva
function calculateTotal($pricePerNight, $checkIn, $checkOut) {
    $start = new DateTime($checkIn);
    $end = new DateTime($checkOut);
    $nights = $start->diff($end)->days;
    return $nights * $pricePerNight;
}

// Verificar disponibilidade do quarto
function checkAvailability($pdo, $roomId, $checkIn, $checkOut) {
    $sql = "SELECT COUNT(*) FROM bookings 
            WHERE room_id = :room_id 
            AND status != 'cancelled'
            AND (
                (check_in BETWEEN :check_in AND :check_out)
                OR (check_out BETWEEN :check_in AND :check_out)
            )";

    $stmt = $pdo->prepare($sql);
    $stmt->execute([
        ':room_id' => $roomId,
        ':check_in' => $checkIn,
        ':check_out' => $checkOut
    ]);

    return $stmt->fetchColumn() == 0;
}

// Formatar moeda
function formatCurrency($value) {
    return 'R$ ' . number_format($value, 2, ',', '.');
}

// Gerar código de reserva único
function generateBookingCode() {
    return strtoupper(uniqid('BK'));
}
