<?php
class Room {
    private $pdo;
    private $table = 'rooms';

    public function __construct($pdo) {
        $this->pdo = $pdo;
    }

    // Buscar todos os quartos
    public function getAll() {
        $stmt = $this->pdo->query(
            "SELECT * FROM {$this->table} WHERE status = 'available'"
        );
        return $stmt->fetchAll();
    }

    // Buscar quarto por ID
    public function getById($id) {
        $stmt = $this->pdo->prepare(
            "SELECT * FROM {$this->table} WHERE id = :id"
        );
        $stmt->execute([':id' => $id]);
        return $stmt->fetch();
    }

    // Buscar quartos disponíveis por data
    public function getAvailable($checkIn, $checkOut) {
        $sql = "SELECT r.* FROM rooms r
                WHERE r.id NOT IN (
                    SELECT b.room_id FROM bookings b
                    WHERE b.status != 'cancelled'
                    AND (
                        (b.check_in BETWEEN :check_in AND :check_out)
                        OR (b.check_out BETWEEN :check_in AND :check_out)
                    )
                )";

        $stmt = $this->pdo->prepare($sql);
        $stmt->execute([
            ':check_in' => $checkIn,
            ':check_out' => $checkOut
        ]);
        return $stmt->fetchAll();
    }
}
