## Controllers

### app/controllers/BookingController.php
```php
<?php
require_once 'app/models/Booking.php';
require_once 'app/models/Room.php';

class BookingController {
    private $bookingModel;
    private $roomModel;

    public function __construct($pdo) {
        $this->bookingModel = new Booking($pdo);
        $this->roomModel = new Room($pdo);
    }

    // Exibir formulário de reserva
    public function create() {
        $roomId = isset($_GET['room_id']) ? (int)$_GET['room_id'] : null;
        $room = $this->roomModel->getById($roomId);

        if(!$room) {
            header('Location: /hotel/rooms');
            exit;
        }

        require 'app/views/booking/create.php';
    }

    // Processar reserva
    public function store() {
        if($_SERVER['REQUEST_METHOD'] !== 'POST') {
            header('Location: /hotel/rooms');
            exit;
        }

        // Validar dados
        $checkIn  = sanitize($_POST['check_in']);
        $checkOut = sanitize($_POST['check_out']);
        $roomId   = (int)$_POST['room_id'];

        $validation = validateDates($checkIn, $checkOut);
        if($validation !== true) {
            $_SESSION['error'] = $validation;
            header('Location: /hotel/booking/create?room_id='.$roomId);
            exit;
        }

        // Verificar disponibilidade
        $room = $this->roomModel->getById($roomId);
        $total = calculateTotal($room['price'], $checkIn, $checkOut);

        // Criar reserva
        $data = [
            'user_id'     => $_SESSION['user_id'],
            'room_id'     => $roomId,
            'check_in'    => $checkIn,
            'check_out'   => $checkOut,
            'total_price' => $total
        ];

        if($this->bookingModel->create($data)) {
            $_SESSION['success'] = "Reserva realizada com sucesso!";
            header('Location: /hotel/booking/list');
        } else {
            $_SESSION['error'] = "Erro ao realizar reserva";
            header('Location: /hotel/booking/create?room_id='.$roomId);
        }
        exit;
    }

    // Listar reservas do usuário
    public function list() {
        $bookings = $this->bookingModel->getByUser($_SESSION['user_id']);
        require 'app/views/booking/list.php';
    }
}
```

