### 3. Advanced Multi-Class Classification Inference

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <fann.h>

class ClassificationInference {
private:
    struct fann* ann_;
    std::vector<std::string> class_labels_;

public:
    ClassificationInference(const std::string& model_path,
                             const std::vector<std::string>& labels)
        : ann_(nullptr), class_labels_(labels) {

        ann_ = fann_create_from_file(model_path.c_str());
        if (!ann_) throw std::runtime_error("Cannot load model");
    }

    ~ClassificationInference() {
        if (ann_) fann_destroy(ann_);
    }

    // ─── Get class probabilities ──────────────
    std::vector<float> getProbs(const std::vector<float>& input) {

        std::vector<fann_type> fann_in(input.begin(), input.end());
        fann_type* raw = fann_run(ann_, fann_in.data());

        unsigned int n = fann_get_num_output(ann_);
        std::vector<float> probs(raw, raw + n);

        return probs;
    }

    // ─── Get top-1 class ─────────────────────
    std::pair<std::string, float> predictClass(
        const std::vector<float>& input) {

        auto probs = getProbs(input);

        auto max_it = std::max_element(probs.begin(), probs.end());
        int  max_idx = std::distance(probs.begin(), max_it);

        std::string label = (max_idx < (int)class_labels_.size())
            ? class_labels_[max_idx]
            : "Class_" + std::to_string(max_idx);

        return {label, *max_it};
    }

    // ─── Get top-N predictions ────────────────
    std::vector<std::pair<std::string, float>> topN(
        const std::vector<float>& input, int n) {

        auto probs = getProbs(input);

        // Sort indices by probability
        std::vector<int> indices(probs.size());
        std::iota(indices.begin(), indices.end(), 0);
        std::sort(indices.begin(), indices.end(),
            [&probs](int a, int b) {
                return probs[a] > probs[b];
            });

        std::vector<std::pair<std::string, float>> results;
        for (int i = 0; i < std::min(n, (int)indices.size()); i++) {
            int idx = indices[i];
            std::string label = (idx < (int)class_labels_.size())
                ? class_labels_[idx]
                : "Class_" + std::to_string(idx);
            results.push_back({label, probs[idx]});
        }

        return results;
    }
};

// ─── Usage ────────────────────────────────────
int main() {
    std::vector<std::string> labels = {
        "Cat", "Dog", "Bird", "Fish"
    };

    try {
        ClassificationInference model("classifier.net", labels);

        std::vector<float> sample = {0.1f, 0.5f, 0.3f, 0.8f, 0.2f};

        // Single prediction
        auto [predicted_class, confidence] = model.predictClass(sample);
        std::cout << "Predicted: " << predicted_class 
                  << " (confidence: " << confidence << ")" << std::endl;

        // Top-3 predictions
        auto top3 = model.topN(sample, 3);
        std::cout << "\nTop-3 Predictions:" << std::endl;
        for (int i = 0; i < (int)top3.size(); i++) {
            printf("  %d. %-10s %.4f\n", 
                i+1, top3[i].first.c_str(), top3[i].second);
        }

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
