# A* Pathfinding in C#

Here's a complete A* pathfinding implementation for your method:

```csharp
using System.Collections.Generic;
using UnityEngine;

public class Pathfinder
{
    public List<Vector2Int> FindPath(int[,] map, Vector2Int start, Vector2Int destination)
    {
        int width = map.GetLength(0);
        int height = map.GetLength(1);

        // Nodes for tracking path data
        Dictionary<Vector2Int, Vector2Int> cameFrom = new Dictionary<Vector2Int, Vector2Int>();
        Dictionary<Vector2Int, float> gScore = new Dictionary<Vector2Int, float>();
        Dictionary<Vector2Int, float> fScore = new Dictionary<Vector2Int, float>();

        // Priority queue (sorted by fScore)
        List<Vector2Int> openSet = new List<Vector2Int>();
        HashSet<Vector2Int> closedSet = new HashSet<Vector2Int>();

        // Initialize
        gScore[start] = 0;
        fScore[start] = Heuristic(start, destination);
        openSet.Add(start);

        while (openSet.Count > 0)
        {
            // Get node with lowest fScore
            Vector2Int current = GetLowestFScore(openSet, fScore);

            // Reached destination
            if (current == destination)
                return ReconstructPath(cameFrom, current);

            openSet.Remove(current);
            closedSet.Add(current);

            // Check all neighbors
            foreach (Vector2Int neighbor in GetNeighbors(current, map, width, height))
            {
                if (closedSet.Contains(neighbor))
                    continue;

                float tentativeGScore = gScore.GetValueOrDefault(current, float.MaxValue) + 1;

                if (!openSet.Contains(neighbor))
                    openSet.Add(neighbor);
                else if (tentativeGScore >= gScore.GetValueOrDefault(neighbor, float.MaxValue))
                    continue;

                // Best path so far
                cameFrom[neighbor] = current;
                gScore[neighbor] = tentativeGScore;
                fScore[neighbor] = tentativeGScore + Heuristic(neighbor, destination);
            }
        }

        // No path found
        return null;
    }

    // ─── Helper Methods ───────────────────────────────────────────

    private float Heuristic(Vector2Int a, Vector2Int b)
    {
        // Manhattan distance (good for grid-based movement)
        return Mathf.Abs(a.x - b.x) + Mathf.Abs(a.y - b.y);
    }

    private Vector2Int GetLowestFScore(List<Vector2Int> openSet, Dictionary<Vector2Int, float> fScore)
    {
        Vector2Int lowest = openSet[0];
        foreach (var node in openSet)
        {
            if (fScore.GetValueOrDefault(node, float.MaxValue) <
                fScore.GetValueOrDefault(lowest, float.MaxValue))
            {
                lowest = node;
            }
        }
        return lowest;
    }

    private List<Vector2Int> GetNeighbors(Vector2Int node, int[,] map, int width, int height)
    {
        List<Vector2Int> neighbors = new List<Vector2Int>();

        Vector2Int[] directions = {
            Vector2Int.up,
            Vector2Int.down,
            Vector2Int.left,
            Vector2Int.right
        };

        foreach (var dir in directions)
        {
            Vector2Int neighbor = node + dir;

            // Bounds check
            if (neighbor.x < 0 || neighbor.x >= width ||
                neighbor.y < 0 || neighbor.y >= height)
                continue;

            // Walkable check (0 = walkable, 1 = wall)
            if (map[neighbor.x, neighbor.y] == 0)
                neighbors.Add(neighbor);
        }

        return neighbors;
    }

    private List<Vector2Int> ReconstructPath(Dictionary<Vector2Int, Vector2Int> cameFrom, Vector2Int current)
    {
        List<Vector2Int> path = new List<Vector2Int>();
        path.Add(current);

        while (cameFrom.ContainsKey(current))
        {
            current = cameFrom[current];
            path.Add(current);
        }

        path.Reverse(); // Start → Destination
        return path;
    }
}
