    public interface Shape
    {
        void Input();
        void OutScreen();
    }

    // ╔══════════════════════════════════╗
    // ║           Класс Точка            ║
    // ╚══════════════════════════════════╝
    class myPoint : Shape
    {
        int x, y;

        public void Input()
        {
            Console.WriteLine("Введите координату X точки:");
            x = int.Parse(Console.ReadLine());

            Console.WriteLine("Введите координату Y точки:");
            y = int.Parse(Console.ReadLine());
        }

        public void OutScreen()
        {
            Console.WriteLine($"Точка -> X: {x}, Y: {y}");
        }
    }

    // ╔══════════════════════════════════╗
    // ║           Класс Круг             ║
    // ╚══════════════════════════════════╝
    class myCircle : Shape
    {
        int x0, y0, r;

        public void Input()
        {
            Console.WriteLine("Введите X центра круга:");
            x0 = int.Parse(Console.ReadLine());

            Console.WriteLine("Введите Y центра круга:");
            y0 = int.Parse(Console.ReadLine());

            Console.WriteLine("Введите радиус круга:");
            r = int.Parse(Console.ReadLine());
        }

        public void OutScreen()
        {
            Console.WriteLine($"Круг -> X0: {x0}, Y0: {y0}, R: {r}");
        }
    }

    // ╔══════════════════════════════════╗
    // ║          Класс Квадрат           ║
    // ╚══════════════════════════════════╝
    class mySquare : Shape
    {
        int side;   // сторона квадрата
        int square; // площадь

        public void Input()
        {
            Console.WriteLine("Введите сторону квадрата:");
            side = int.Parse(Console.ReadLine());
            square = side * side; // вычисляем площадь
        }

        public void OutScreen()
        {
            Console.WriteLine($"Квадрат -> Сторона: {side}, Площадь: {square}");
        }
    }

    // ╔══════════════════════════════════╗
    // ║          Главный класс           ║
    // ╚══════════════════════════════════╝
    class Program
    {
        static void Main(string[] args)
        {
            // Массив фигур (полиморфизм через интерфейс)
            Shape[] shapes =
            {
                new myPoint(),
                new myCircle(),
                new mySquare()
            };

            // ── Ввод данных для каждой фигуры ──
            Console.WriteLine("=== ВВОД ДАННЫХ ===\n");
            foreach (Shape s in shapes)
            {
                s.Input();
                Console.WriteLine(); // отступ между фигурами
            }

            // ── Вывод данных для каждой фигуры ──
            Console.WriteLine("=== РЕЗУЛЬТАТ ===\n");
            foreach (Shape s in shapes)
            {
                s.OutScreen();
            }

            Console.ReadLine();
        }
    }
}
```

