## 2. Componente TypeScript

```typescript
// dynamic-form.component.ts
import { Component, Input, OnInit, OnChanges, SimpleChanges, Output, EventEmitter } from '@angular/core';
import {
  FormBuilder,
  FormGroup,
  Validators,
  AbstractControl,
  ValidatorFn,
  ReactiveFormsModule
} from '@angular/forms';
import { CommonModule } from '@angular/common';
import { FormField } from './form-field.interface';

@Component({
  selector: 'app-dynamic-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './dynamic-form.component.html',
  styleUrls: ['./dynamic-form.component.scss']
})
export class DynamicFormComponent implements OnInit, OnChanges {

  @Input() fields: FormField[] = [];
  @Input() submitLabel: string = 'Enviar';
  @Input() showReset: boolean = true;

  @Output() formSubmit = new EventEmitter<any>();
  @Output() formChange = new EventEmitter<any>();

  form!: FormGroup;
  sortedFields: FormField[] = [];

  constructor(private fb: FormBuilder) {}

  ngOnInit(): void {
    this.buildForm();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['fields'] && !changes['fields'].firstChange) {
      this.buildForm();
    }
  }

  // ──────────────────────────────────────────
  // Construcción del formulario
  // ──────────────────────────────────────────
  private buildForm(): void {
    this.sortedFields = [...this.fields].sort(
      (a, b) => (a.order ?? 0) - (b.order ?? 0)
    );

    const group: { [key: string]: any } = {};

    this.sortedFields.forEach(field => {
      const validators = this.getValidators(field);
      group[field.key] = [
        { value: field.value ?? '', disabled: field.disabled ?? false },
        validators
      ];
    });

    this.form = this.fb.group(group);

    // Emitir cambios en tiempo real
    this.form.valueChanges.subscribe(value => {
      this.formChange.emit(value);
    });
  }

  // ──────────────────────────────────────────
  // Obtener validadores dinámicamente
  // ──────────────────────────────────────────
  private getValidators(field: FormField): ValidatorFn[] {
    const validators: ValidatorFn[] = [];

    if (field.required)              validators.push(Validators.required);
    if (field.minLength)             validators.push(Validators.minLength(field.minLength));
    if (field.maxLength)             validators.push(Validators.maxLength(field.maxLength));
    if (field.min !== undefined)     validators.push(Validators.min(field.min));
    if (field.max !== undefined)     validators.push(Validators.max(field.max));
    if (field.pattern)               validators.push(Validators.pattern(field.pattern));
    if (field.type === 'email')      validators.push(Validators.email);

    return validators;
  }

  // ──────────────────────────────────────────
  // Agregar campo dinámicamente
  // ──────────────────────────────────────────
  addField(field: FormField): void {
    this.fields = [...this.fields, field];
    const validators = this.getValidators(field);
    this.form.addControl(
      field.key,
      this.fb.control(
        { value: field.value ?? '', disabled: field.disabled ?? false },
        validators
      )
    );
    this.sortedFields = [...this.fields].sort(
      (a, b) => (a.order ?? 0) - (b.order ?? 0)
    );
  }

  // ──────────────────────────────────────────
  // Eliminar campo dinámicamente
  // ──────────────────────────────────────────
  removeField(key: string): void {
    this.fields = this.fields.filter(f => f.key !== key);
    this.sortedFields = this.sortedFields.filter(f => f.key !== key);
    this.form.removeControl(key);
  }

  // ──────────────────────────────────────────
  // Helpers para la plantilla
  // ──────────────────────────────────────────
  getControl(key: string): AbstractControl {
    return this.form.get(key)!;
  }

  isInvalid(key: string): boolean {
    const control = this.getControl(key);
    return control.invalid && (control.dirty || control.touched);
  }

  getErrorMessage(field: FormField): string {
    const control = this.getControl(field.key);
    const errors = control.errors;

    if (!errors) return '';

    // Mensajes personalizados
    if (field.errorMessages) {
      const firstError = Object.keys(errors)[0];
      if (field.errorMessages[firstError]) {
        return field.errorMessages[firstError];
      }
    }

    // Mensajes por defecto
    if (errors['required'])   return `${field.label} es requerido`;
    if (errors['email'])      return 'Ingrese un email válido';
    if (errors['minlength'])  return `Mínimo ${errors['minlength'].requiredLength} caracteres`;
    if (errors['maxlength'])  return `Máximo ${errors['maxlength'].requiredLength} caracteres`;
    if (errors['min'])        return `El valor mínimo es ${errors['min'].min}`;
    if (errors['max'])        return `El valor máximo es ${errors['max'].max}`;
    if (errors['pattern'])    return 'El formato no es válido';

    return 'Campo inválido';
  }

  // ──────────────────────────────────────────
  // Submit y Reset
  // ──────────────────────────────────────────
  onSubmit(): void {
    if (this.form.valid) {
      this.formSubmit.emit(this.form.getRawValue());
    } else {
      this.form.markAllAsTouched();
    }
  }

  onReset(): void {
    this.form.reset();
    this.fields.forEach(field => {
      if (field.value !== undefined) {
        this.form.get(field.key)?.setValue(field.value);
      }
    });
  }
}
```

