## 3. Template HTML

```html
<!-- dynamic-form.component.html -->
<form [formGroup]="form" (ngSubmit)="onSubmit()" novalidate>

  <div class="form-grid">

    <div
      class="form-group"
      *ngFor="let field of sortedFields"
      [class.has-error]="isInvalid(field.key)">

      <!-- Label -->
      <label [for]="field.key">
        {{ field.label }}
        <span class="required" *ngIf="field.required">*</span>
      </label>

      <!-- INPUT TEXT / EMAIL / PASSWORD / NUMBER / DATE -->
      <ng-container *ngIf="['text','email','password','number','date'].includes(field.type)">
        <input
          [id]="field.key"
          [type]="field.type"
          [formControlName]="field.key"
          [placeholder]="field.placeholder || ''"
          class="form-control"
          [class.invalid]="isInvalid(field.key)">
      </ng-container>

      <!-- TEXTAREA -->
      <ng-container *ngIf="field.type === 'textarea'">
        <textarea
          [id]="field.key"
          [formControlName]="field.key"
          [placeholder]="field.placeholder || ''"
          class="form-control textarea"
          [class.invalid]="isInvalid(field.key)"
          rows="4">
        </textarea>
      </ng-container>

      <!-- SELECT -->
      <ng-container *ngIf="field.type === 'select'">
        <select
          [id]="field.key"
          [formControlName]="field.key"
          class="form-control"
          [class.invalid]="isInvalid(field.key)">
          <option value="" disabled>-- Seleccione --</option>
          <option
            *ngFor="let option of field.options"
            [value]="option.value">
            {{ option.label }}
          </option>
        </select>
      </ng-container>

      <!-- CHECKBOX -->
      <ng-container *ngIf="field.type === 'checkbox'">
        <div class="checkbox-wrapper">
          <input
            [id]="field.key"
            type="checkbox"
            [formControlName]="field.key"
            class="checkbox">
          <span class="checkbox-label">{{ field.placeholder }}</span>
        </div>
      </ng-container>

      <!-- Mensaje de error -->
      <span class="error-message" *ngIf="isInvalid(field.key)">
        {{ getErrorMessage(field) }}
      </span>

    </div>
  </div>

  <!-- Botones -->
  <div class="form-actions">
    <button
      type="button"
      class="btn btn-secondary"
      *ngIf="showReset"
      (click)="onReset()">
      Limpiar
    </button>

    <button
      type="submit"
      class="btn btn-primary"
      [disabled]="form.invalid">
      {{ submitLabel }}
    </button>
  </div>

  <!-- Estado del formulario (debug) -->
  <details class="debug" style="margin-top: 1rem">
    <summary>Debug: Estado del formulario</summary>
    <pre>{{ form.value | json }}</pre>
    <small>Válido: {{ form.valid }}</small>
  </details>

</form>
