            flex-direction: column;
            align-items: center;
            margin-top: 50px;
        }

        #myBox {
            width: 300px;
            padding: 20px;
            background-color: #4CAF50;
            color: white;
            text-align: center;
            border-radius: 8px;
            margin-top: 20px;
            font-size: 18px;
        }

        button {
            padding: 10px 25px;
            font-size: 16px;
            cursor: pointer;
            background-color: #008CBA;
            color: white;
            border: none;
            border-radius: 6px;
        }

        button:hover {
            background-color: #005f7f;
        }
    </style>
</head>
<body>

    <h2>Show / Hide Example</h2>

    <button onclick="toggleBox()">Show / Hide</button>

    <div id="myBox">
        Hello! I am visible now 👋
    </div>

    <script>
        function toggleBox() {
            var box = document.getElementById("myBox");

            // IF CONDITION to check show or hide
            if (box.style.display === "none") {
                // If hidden → SHOW it
                box.style.display = "block";
                console.log("Box is now VISIBLE");
            } else {
                // If visible → HIDE it
                box.style.display = "none";
                console.log("Box is now HIDDEN");
            }
        }
    </script>

</body>
</html>
```

---

## How It Works 👇

| Condition | Action |
|-----------|--------|
| `display === "none"` | Show the element (`display = "block"`) |
| `display !== "none"` | Hide the element (`display = "none"`) |

---

## Key Points ✅

- **`onclick`** calls the `toggleBox()` function
- **`if` condition** checks if the box is hidden or visible
- **`display = "none"`** → hides the element
- **`display = "block"`** → shows the element

## Prime Number Test in JavaScript

Here's a JavaScript program that tests if a number is prime:

### Basic Implementation

```javascript
function isPrime(num) {
  // Handle edge cases
  if (num < 2) return false;
  if (num === 2) return true;
  if (num % 2 === 0) return false;

  // Check odd divisors up to square root
  for (let i = 3; i <= Math.sqrt(num); i += 2) {
    if (num % i === 0) return false;
  }

  return true;
}

// Test the function
const testNumbers = [1, 2, 3, 4, 17, 25, 97, 100];

testNumbers.forEach(num => {
  console.log(`${num} is ${isPrime(num) ? "" : "not "}prime`);
});
```

### Output

```
1 is not prime
2 is prime
3 is prime
4 is not prime
17 is prime
25 is not prime
97 is prime
100 is not prime
```

---

### How It Works

| Check | Reason |
|-------|--------|
| `num < 2` | Numbers less than 2 are not prime |
| `num === 2` | 2 is the only even prime number |
| `num % 2 === 0` | Eliminate all other even numbers |
| Loop to `√num` | If no divisor found by √num, number is prime |
| Step by 2 (`i += 2`) | Skip even numbers in the loop |

> **Why only check up to √num?**
> If a number `n` has a factor greater than `√n`, then it must also
> have a factor **smaller** than `√n` — so we don't need to check further.

---

### Interactive Version (Browser/Node.js)

```javascript
function isPrime(num) {
  if (num < 2) return false;
  if (num === 2) return true;
  if (num % 2 === 0) return false;

  for (let i = 3; i <= Math.sqrt(num); i += 2) {
    if (num % i === 0) return false;
  }

  return true;
}

// Get user input (Node.js)
const readline = require("readline").createInterface({
  input: process.stdin,
  output: process.stdout,
});

readline.question("Enter a number: ", (input) => {
  const num = parseInt(input);

  if (isNaN(num)) {
    console.log("Please enter a valid number.");
  } else {
    console.log(`${num} is ${isPrime(num) ? "" : "not "}prime.`);
  }

  readline.close();
});
```

### Example Run

```
Enter a number: 37
37 is prime.
```

