    APP_ID,
    arrayOf(ZONE_ID),   // Array of Zone IDs
    appOptions,
    object : AdColonyInitializationListener {
        override fun onSuccess() {
            // Initialization successful
        }
        override fun onError(error: AdColonyAdRequestError) {
            // Handle error
        }
    }
)
