## Enhanced Version with Options

```csharp
using QRCoder;

class Program
{
    static void Main(string[] args)
    {
        if (args.Length == 0 || args[0] == "--help" || args[0] == "-h")
        {
            PrintHelp();
            Environment.Exit(args.Length == 0 ? 1 : 0);
        }

        var options = ParseArguments(args);

        try
        {
            GenerateQRCode(options);
            Console.WriteLine($"QR code saved to: {options.OutputFile}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
            Environment.Exit(1);
        }
    }

    static QROptions ParseArguments(string[] args)
    {
        var options = new QROptions
        {
            Text = args[0],
            OutputFile = "qrcode.png",
            PixelsPerModule = 20,
            EccLevel = QRCodeGenerator.ECCLevel.Q
        };

        for (int i = 1; i < args.Length; i++)
        {
            switch (args[i])
            {
                case "-o" or "--output" when i + 1 < args.Length:
                    options.OutputFile = args[++i];
                    break;

                case "-s" or "--size" when i + 1 < args.Length:
                    if (int.TryParse(args[++i], out int size) && size > 0)
                        options.PixelsPerModule = size;
                    break;

                case "-e" or "--ecc" when i + 1 < args.Length:
                    options.EccLevel = args[++i].ToUpper() switch
                    {
                        "L" => QRCodeGenerator.ECCLevel.L,
                        "M" => QRCodeGenerator.ECCLevel.M,
                        "Q" => QRCodeGenerator.ECCLevel.Q,
                        "H" => QRCodeGenerator.ECCLevel.H,
                        _ => QRCodeGenerator.ECCLevel.Q
                    };
                    break;

                default:
                    Console.WriteLine($"Unknown argument: {args[i]}");
                    break;
            }
        }

        return options;
    }

    static void GenerateQRCode(QROptions options)
    {
        using QRCodeGenerator qrGenerator = new QRCodeGenerator();
        using QRCodeData qrCodeData = qrGenerator.CreateQrCode(
            options.Text,
            options.EccLevel
        );
        using PngByteQRCode qrCode = new PngByteQRCode(qrCodeData);

        byte[] qrCodeBytes = qrCode.GetGraphic(options.PixelsPerModule);
        File.WriteAllBytes(options.OutputFile, qrCodeBytes);
    }

    static void PrintHelp()
    {
        Console.WriteLine("QR Code Generator");
        Console.WriteLine("=================");
        Console.WriteLine("Usage: QRGenerator <text> [options]");
        Console.WriteLine();
        Console.WriteLine("Options:");
        Console.WriteLine("  -o, --output <file>   Output file path (default: qrcode.png)");
        Console.WriteLine("  -s, --size <pixels>   Pixels per module (default: 20)");
        Console.WriteLine("  -e, --ecc <level>     Error correction level: L, M, Q, H (default: Q)");
        Console.WriteLine("  -h, --help            Show this help message");
        Console.WriteLine();
        Console.WriteLine("Examples:");
        Console.WriteLine("  QRGenerator \"https://example.com\"");
        Console.WriteLine("  QRGenerator \"Hello World\" -o hello.png -s 10");
        Console.WriteLine("  QRGenerator \"My Text\" --output out.png --ecc H");
    }
}

class QROptions
{
    public string Text { get; set; } = string.Empty;
    public string OutputFile { get; set; } = "qrcode.png";
    public int PixelsPerModule { get; set; } = 20;
    public QRCodeGenerator.ECCLevel EccLevel { get; set; } = QRCodeGenerator.ECCLevel.Q;
}
```

## Example Usage

```bash
# Simple URL
dotnet run "https://github.com"

# Custom output and size
dotnet run "https://github.com" -o github.png -s 15

# High error correction
dotnet run "Contact Info" --output contact.png --ecc H --size 25
